using System;using System.Text;using OpenMetaverse;using OpenMetaverse.StructuredData;using GridRegion=OpenSim.Services.Interfaces.GridRegion;
namespace OpenSim.Services.Interfaces{public class GridRegion{public UUID RegionID;public int RegionLocX,RegionLocY;public string RegionName,ServerURI;}}
public interface ISceneObject{UUID UUID{get;}string ToXml2();string ExtraToXmlString();bool HasGroupChanged{get;}string GetStateSnapshot();}
public class Context{public OSDMap command;public string trace="";public GridRegion region;public void Log(string op){trace+=op+";";if(command["failure"].AsString()==op)throw new Exception();}}
public static class WebUtil{public static Context ctx;public static OSDMap PostToService(string uri,OSDMap args,int timeout,bool compressed){ctx.Log("request");ctx.trace+=RemoteObject.H(uri)+":"+timeout+":"+(compressed?"1":"0")+":"+RemoteObject.H(OSDParser.SerializeJsonString(args,true))+";";return ctx.command["reply"] as OSDMap;}}
public class Log{public void WarnFormat(string s,params object[] args){}}
public partial class RemoteObject{public Context ctx;Log m_log=new();protected virtual string ObjectPath(){ctx.Log("path");return ctx.command["custom"].AsBoolean()?"custom/object/":"object/";}public static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();class Obj:ISceneObject{Context ctx;public Obj(Context c){ctx=c;}public UUID UUID{get{ctx.Log("uuid");return new UUID("00000000-0000-0000-0000-000000000007");}}public string ToXml2(){ctx.Log("xml");if(ctx.command["mutate"].AsBoolean()){ctx.region.RegionLocX=-123;ctx.region.RegionName="changed";}return ctx.command.ContainsKey("xml")?ctx.command["xml"].AsString():"<object/>";}public string ExtraToXmlString(){ctx.Log("extra");return ctx.command["extra"].AsString();}public bool HasGroupChanged{get{ctx.Log("modified");return ctx.command["modified"].AsBoolean();}}public string GetStateSnapshot(){ctx.Log("state");return ctx.command["null_state"].AsBoolean()?null:ctx.command["state"].AsString();}}
public static void Main(){System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var ctx=new Context{command=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)))};ctx.region=new GridRegion{RegionID=new UUID("00000000-0000-0000-0000-000000000009"),RegionLocX=25600,RegionLocY=51200,RegionName=ctx.command["null_name"].AsBoolean()?null:"Destination",ServerURI="http://sim:9000/base/"};WebUtil.ctx=ctx;var handler=new RemoteObject{ctx=ctx};string result;try{bool ok=ctx.command["inventory"].AsBoolean()?handler.CreateObject(null,UUID.Zero,UUID.Zero):handler.CreateObject(ctx.command["null_destination"].AsBoolean()?null:ctx.region,new Vector3(1.25f,2,30),ctx.command["null_object"].AsBoolean()?null:new Obj(ctx),ctx.command["local"].AsBoolean());result=ok?"1":"0";}catch{result="EX";}Console.WriteLine(result+"|"+H(ctx.trace));}}}
